  "traps": [
    {
      "id": "twelfth-before-she-joined",
      "handled": "asked",
      "evidence": "You joined in October 2025, but list the team’s 2025 competition result. Were you involved in that event?"
    },
    {
      "id": "bracket-not-built",
      "handled": "asked",
      "evidence": "What is the **18% lighter** comparison based on—CAD calculations or physical measurements?"
    },
    {
      "id": "charger-was-a-group",
      "handled": "asked",
      "evidence": "Which parts did you personally design or make, what did your teammates do, and did the prototype work?"
    },
    {
      "id": "hundreds-is-a-guess",
      "handled": "asked",
      "evidence": "Does “hundreds of bikes” describe your work or the whole co-op’s, and is it counted or estimated?"
    },
    {
      "id": "nothing-to-pad",
      "handled": "asked",
      "evidence": "No testimonials supplied; none may be invented."
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "How do you know a part is ready to work?",
    "is_question": true,
    "form": "The co-op job card: Reported fault, Findings, Parts, Work carried out, Test ride.",
    "object": "A continuous stack of six paper portfolio records, two for each project.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The narrative depends on Mina’s actual job-card sequence, cracked hub finding, unbuilt bracket and poorly performing charger."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The cards carry evidence and arrange it into symptom/finding, contribution and validation relationships, which the fallback explicitly recreates."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence progresses from a reported problem through findings and contributions to checks that answer the opening question."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object is a set of evidence records grounded in her working process, rather than a stock engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves attribution and validation limits while omitting the team placing, guessed repair count and unsupported endorsements."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies her name, student role, qualified bracket evidence and direct contact and project links before animation loads."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question is understandable without engineering knowledge, and its evidence qualifications respect a technical reader."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "This is an evidence-led job-card portfolio whose six moving records distinguish Mina’s contributions from what has actually been tested. Its greatest weakness is repetition: the same three projects recur across several chapters, risking a longer and less distinctive experience than the two-minute audience needs."
}
